// Deterministic standard-code parser — TypeScript port of parse_data's
// src/parsers/std_code_parser.py (parse_standard_code + helpers it calls).
//
// Field names stay snake_case to match the Python result dict 1:1; the
// golden fixture in tests/fixtures/code-parser-golden.json is generated by
// running the original Python code (see generate-golden.py) and
// tests/code-parser.golden.test.ts asserts field-by-field equality.
//
// Settled rules preserved exactly:
// - explicit ranges ("1 đến 10", "các phần 1, 2, 5, 6, 7") expand per part,
//   keeping the year on each part;
// - a bare hyphen "MAIN-A-B" is Part A, Chapter B — NOT a range;
// - combined org prefixes ("BS EN", "TCVN EN", "GB/T", "GB/Z") are distinct
//   designations and are never reduced;
// - never invent a year, part, or equivalent the source does not contain.
//
// Known deliberate divergences from Python (documented, behaviour-equal for
// real inputs): ASCII-only \d (Python \d also matches non-ASCII digits),
// null/undefined input treated as "" (Python raises), confidence computed
// in integer milliunits instead of Decimal (identical results: every
// component is an exact multiple of 0.01).
//
// Intentional TS-only fixes (user decision 2026-11-23, marked as
// `divergence` in the golden fixture; the Python parser is NOT modified):
// - amendment/corrigendum tokens (AMD, COR, AC, A<n>) are recognized with
//   OR without a space ("Amd 1:2016" -> "AMD1:2016"); Python drops the
//   spaced form as multi-word prose, losing the amendment entirely;
// - COR is recognized as a corrigendum marker (Python's amendment regex
//   does not include it);
// - an unparsed multi-word remainder is kept (space-stripped) in `suffix`
//   instead of dropped, so its normalized_code can never collide with the
//   base code's key.

export interface ParsedStandardCode {
  raw_code: string;
  normalized_code: string;
  org_prefix: string | null;
  org_normalized: string | null;
  org_confidence: number;
  series_number: string | null;
  series_letter: string | null;
  std_main_number: string | null;
  std_part: string | null;
  std_parts: string[];
  std_code_full: string | null;
  parts_kind: 'range' | 'list' | null;
  expanded_parts: string[] | null;
  std_year: number | null;
  amendment: string | null;
  suffix: string | null;
  version_text: string | null;
  equivalent_text: string | null;
  confidence_score: number;
  confidence_breakdown: Record<string, number>;
  verified: boolean;
}

// -------------------------------------------------
// ORG NORMALIZATION MAP (same insertion order as Python)
// -------------------------------------------------
// Longest-first startswith matching is used in normalizeOrg, so
// multi-word keys (TCVN/ISO, EN ISO, BS EN, DIN EN) win over their
// single-word prefixes.
const ORG_MAP_ENTRIES: ReadonlyArray<readonly [string, string]> = [
  ['TCVN', 'TCVN'],
  ['TCVN/ISO', 'TCVN'],
  // Preserve this literal combined prefix when it appears in source data.
  // Without an exact entry, normalizeOrg's startswith fallback reduced
  // "TCVN EN" to "TCVN", dropping the trailing designation.
  ['TCVN EN', 'TCVN EN'],
  ['QCVN', 'QCVN'],
  ['ISO', 'ISO'],
  ['EN', 'EN'],
  ['EN ISO', 'ISO'],
  // Preserve this literal combined prefix when it appears in source data.
  // "BS EN" is the British adoption of an EN standard, a different
  // designation from a bare "EN"; reducing it to "EN" dropped the
  // "BS" from the corrected code. Same rule as "TCVN EN".
  ['BS EN', 'BS EN'],
  ['BS', 'BS'],
  ['DIN EN', 'EN'],
  ['DIN ISO', 'DIN'],
  ['DIN', 'DIN'],
  ['IEC', 'IEC'],
  ['TCCS', 'TCCS'],
  ['GB', 'GB'],
  // "GB/T" (recommended) and "GB/Z" (guidance) are distinct
  // designations from a bare "GB": preserve the suffix.
  ['GB/T', 'GB/T'],
  ['GB/Z', 'GB/Z'],
  ['CISPR', 'CISPR'],
  ['JIS', 'JIS'],
  ['ASTM', 'ASTM'],
  ['IEEE', 'IEEE'],
  ['ANSI', 'ANSI'],
  ['ASME', 'ASME'],
  ['AASHTO', 'AASHTO'],
  ['AWWA', 'AWWA'],
  ['API', 'API'],
  ['SAE', 'SAE'],
  ['UL', 'UL'],
  ['ULC', 'ULC'],
  ['ENV', 'ENV']
];

export const ORG_MAP: Readonly<Record<string, string>> = Object.fromEntries(ORG_MAP_ENTRIES);

// Python: sorted(ORG_MAP.items(), key=lambda x: -len(x[0])) — stable sort.
const ORG_MAP_BY_LENGTH_DESC: ReadonlyArray<readonly [string, string]> = [
  ...ORG_MAP_ENTRIES
].sort((a, b) => b[0].length - a[0].length);

// Python: sorted(ORG_MAP, key=len, reverse=True) — keys only.
const ORG_KEYS_BY_LENGTH_DESC: readonly string[] = ORG_MAP_ENTRIES.map(([k]) => k).sort(
  (a, b) => b.length - a.length
);

const KNOWN_ORG_PREFIXES = [
  'AASHTO', 'ASTM', 'ASME', 'ANSI', 'IEEE', 'JIS', 'IEC', 'ISO',
  'DIN', 'BS', 'GB', 'EN'
] as const;

// Python: sorted(_KNOWN_ORG_PREFIXES, key=len, reverse=True) — stable sort.
const KNOWN_ORG_PREFIXES_BY_LENGTH_DESC: readonly string[] = [
  ...KNOWN_ORG_PREFIXES
].sort((a, b) => b.length - a.length);

// Bodies whose trailing "-YY" is an edition year, not a part.
const SHORT_YEAR_ORGS: ReadonlySet<string> = new Set(['ASTM', 'AASHTO']);

const EQUIVALENT_ORGS = [
  'TCVN', 'QCVN', 'TCCS', 'ISO', 'IEC', 'EN', 'BS EN', 'BS',
  'DIN EN', 'DIN', 'ASTM', 'JIS', 'ANSI', 'ASME', 'IEEE',
  'SAE', 'API', 'AASHTO', 'AWWA', 'UL', 'GB', 'CISPR'
] as const;

// Expansion limits (mirror Python): guards stop a misread date range or a
// typo range such as "1 đến 1000" from exploding into thousands of records.
const MAX_EXPANDED_PARTS = 100;
const MAX_PART_NUMBER = 999;

export function normalizeText(text: string): string {
  if (!text) return text;

  let t = text.replaceAll('\n', '').replaceAll('\r', '');
  t = t.replaceAll('\t', ' ').replaceAll('\u00A0', ' ');

  t = t.replace(/\s+/g, ' ');
  t = t.replace(/\s*:\s*/g, ':');

  return t.trim();
}

export function normalizeOrg(org: string | null): [string | null, number] {
  if (!org) return [null, 0.0];

  let orgClean = org.trim().toUpperCase();
  // "IEEE Std" / "IEEE-Std" is just IEEE; drop the Std token before matching.
  orgClean = orgClean.replace(/(?:^|[\s-])STD(?:$|[\s-])/g, ' ');
  orgClean = orgClean.replace(/\s+/g, ' ').trim();
  if (!orgClean) return [null, 0.0];

  // STEP 1 — Exact match (LONGEST FIRST)
  for (const [k, v] of ORG_MAP_BY_LENGTH_DESC) {
    if (orgClean.startsWith(k)) return [v, 1.0];
  }

  // STEP 2 — Heuristic
  orgClean = orgClean.replaceAll('/', ' ');
  orgClean = orgClean.replace(/\s+/g, ' ');

  const tokens = orgClean.split(/\s+/).filter((t) => t.length > 0);
  if (tokens.length > 0) {
    const candidate = tokens[0];
    if (/^[A-Z]{2,10}$/.test(candidate)) return [candidate, 0.7];
  }

  // STEP 3 — fallback (Python returns org_clean unstripped here)
  return [orgClean, 0.4];
}

function isYearToken(token: string): boolean {
  // True for a plausible 4-digit publication year (1900-2100).
  if (token.length !== 4 || !/^\d+$/.test(token)) return false;
  const year = Number(token);
  return year >= 1900 && year <= 2100;
}

function shortYear(
  orgNormalized: string | null,
  orgPrefix: string | null,
  token: string
): number | null {
  // Convert a trailing 2-digit edition year, or null. Only for ASTM/AASHTO
  // (and GBJ, whose "GBJ 22-87" form is year 1987). Pivot 50.
  if (token.length !== 2 || !/^\d+$/.test(token)) return null;
  if (
    (orgNormalized !== null && SHORT_YEAR_ORGS.has(orgNormalized)) ||
    orgPrefix === 'GBJ'
  ) {
    const yy = Number(token);
    return yy >= 50 ? 1900 + yy : 2000 + yy;
  }
  return null;
}

interface RemainderResult {
  parts: string[];
  year: number | null;
  suffix: string | null;
  hasCommaList: boolean;
}

function parseRemainder(
  rest: string,
  orgNormalized: string | null,
  orgPrefix: string | null
): RemainderResult {
  // Parse everything after the main number. Parts are hyphen groups that
  // are not a year; year may come after ':', '-', '/', or a space;
  // anything after a resolved year that is not another year is a suffix.
  // A comma list after a hyphen part adds each comma number as a part.
  // A digit token in the year position that is not a valid year
  // (1900-2100) is neither a year nor a suffix and is dropped.
  const parts: string[] = [];
  let year: number | null = null;
  let suffix: string | null = null;
  let hasCommaList = false;
  let s = (rest ?? '').trim();

  while (s) {
    if (s.startsWith(',') && parts.length > 0) {
      const m = /^,\s*(\d+)([\s\S]*)$/.exec(s);
      if (!m) {
        suffix = s;
        break;
      }
      const num = m[1];
      const after = m[2].trim();
      if (isYearToken(num) && year === null) {
        year = Number(num);
        s = after;
        continue;
      }
      parts.push(num);
      hasCommaList = true;
      s = after;
      continue;
    }
    if ((s.startsWith('VÀ ') || s.startsWith('AND ')) && parts.length > 0) {
      const m = /^(?:VÀ|AND)\s+(\d+)([\s\S]*)$/.exec(s);
      if (!m) {
        suffix = s;
        break;
      }
      const num = m[1];
      const after = m[2].trim();
      if (isYearToken(num) && year === null) {
        year = Number(num);
        s = after;
        continue;
      }
      parts.push(num);
      hasCommaList = true;
      s = after;
      continue;
    }
    if (s.startsWith(':')) {
      const m = /^:\s*(\d+)([\s\S]*)$/.exec(s);
      if (m && year === null) {
        const num = m[1];
        const after = m[2].trim();
        if (isYearToken(num)) {
          year = Number(num);
          s = after;
          continue;
        }
        // Year-position token that is not a valid year: drop it.
        s = after;
        continue;
      }
      suffix = s;
      break;
    }
    if (s.startsWith('/')) {
      const m = /^\/\s*(\d+)([\s\S]*)$/.exec(s);
      if (m && year === null) {
        const num = m[1];
        const after = m[2].trim();
        if (isYearToken(num)) {
          year = Number(num);
          s = after;
          continue;
        }
        if (num.length >= 4) {
          s = after;
          continue;
        }
      }
      suffix = s.slice(1).trim() || null;
      break;
    }
    if (s.startsWith('-')) {
      if (year !== null) {
        // e.g. IEC 60850/2007-02, DIN EN 13230-4-2009-10
        suffix = s;
        break;
      }
      const m = /^-\s*(\d+)([\s\S]*)$/.exec(s);
      if (!m) {
        suffix = s;
        break;
      }
      const num = m[1];
      const after = m[2].trim();
      if (isYearToken(num) && year === null) {
        year = Number(num);
        s = after;
        continue;
      }
      const short = shortYear(orgNormalized, orgPrefix, num);
      if (
        (short !== null && year === null && after === '') ||
        (short !== null && year === null && ['+', '/', ':'].includes(after.charAt(0)))
      ) {
        year = short;
        s = after;
        continue;
      }
      parts.push(num);
      s = after;
      continue;
    }
    if (s.startsWith('+')) {
      suffix = s;
      break;
    }
    if (s.startsWith(' ')) {
      const m = /^\s+(\d{4})\b([\s\S]*)$/.exec(s);
      if (m && year === null && isYearToken(m[1])) {
        year = Number(m[1]);
        s = m[2].trim();
        continue;
      }
      const stripped = s.trim();
      if (year === null && /^\d+$/.test(stripped) && stripped.length >= 4) {
        s = '';
        continue;
      }
      suffix = s.trim() || null;
      break;
    }
    if (/^\d+$/.test(s) && year === null && s.length >= 4) {
      // Bare trailing number left after a separator was stripped
      // (e.g. "TCVN 1234-1 2013" -> after "-1", s is "2013").
      if (isYearToken(s)) year = Number(s);
      s = '';
      continue;
    }
    suffix = s;
    break;
  }

  return { parts, year, suffix, hasCommaList };
}

function removeRepeatedOrgPrefix(orgPart: string): string {
  // Collapse an exact duplicate of a known organization prefix
  // (``ENEN`` / ``EN EN``) before the series-letter logic runs.
  const cleaned = (orgPart ?? '').trim().toUpperCase().replace(/\s+/g, ' ');
  for (const known of ORG_KEYS_BY_LENGTH_DESC) {
    const prefix = known.toUpperCase().replace(/\s+/g, ' ').trim();
    if (cleaned === prefix + prefix || cleaned === `${prefix} ${prefix}`) {
      return prefix;
    }
  }
  return cleaned;
}

function extractSeriesLetter(orgPart: string): [string, string | null] {
  // Split a series letter off the org, e.g. 'JIS E' -> ('JIS', 'E').
  // Multi-word orgs such as 'DIN EN' / 'BS EN' / 'EN ISO' are NOT split.
  // Merged forms such as 'JISC' / 'ASTMD' are split when the prefix is a
  // known body.
  const cleaned = removeRepeatedOrgPrefix(orgPart);
  const tokens = cleaned.split(/\s+/).filter((t) => t.length > 0);
  if (tokens.length >= 2) {
    const last = tokens[tokens.length - 1];
    if (last.length === 1 && /^\p{L}$/u.test(last)) {
      return [tokens.slice(0, -1).join(' '), last];
    }
  }
  if (tokens.length === 1) {
    const token = tokens[0];
    for (const known of KNOWN_ORG_PREFIXES_BY_LENGTH_DESC) {
      if (token.startsWith(known) && token.length > known.length) {
        const rest = token.slice(known.length);
        if (/^\p{L}+$/u.test(rest) && rest.length <= 2) {
          return [known, rest];
        }
      }
    }
  }
  return [cleaned, null];
}

// -------------------------------------------------
// CONFIDENCE ENGINE (integer milliunits == Python Decimal results)
// -------------------------------------------------
function computeConfidence(result: ParsedStandardCode): [number, Record<string, number>] {
  let scoreMilli = 0;
  const breakdown: Record<string, number> = {};

  // org
  if (result.org_prefix) {
    const orgConfMilli = Math.round(result.org_confidence * 1000);
    const valMilli = Math.round((200 * orgConfMilli) / 1000);
    scoreMilli += valMilli;
    breakdown['org'] = valMilli / 1000;
  }

  // main
  if (result.std_main_number) {
    scoreMilli += 300;
    breakdown['main'] = 0.3;
  }

  // year
  if (result.std_year) {
    scoreMilli += 300;
    breakdown['year'] = 0.3;
  }

  // parts
  if (result.std_parts.length > 0) {
    scoreMilli += 100;
    breakdown['parts'] = 0.1;
  }

  // suffix
  if (result.amendment || result.suffix) {
    scoreMilli += 100;
    breakdown['suffix'] = 0.1;
  }

  return [scoreMilli / 1000, breakdown];
}

function extractPartRangeFromVersion(versionText: string | null): string[] {
  // Extract a part range/list from a parenthetical note, or [].
  // "các phần 1-6" / "phần 1 đến 3" -> ["1", "6"]; "các phần 1, 3, 5" ->
  // ["1", "3", "5"]. Notes such as "(rev 1)" return [].
  if (!versionText) return [];
  const text = versionText.trim().toLowerCase();
  const hasPartKeyword = text.includes('phần') || text.includes('part');
  const hasRangeWord = text.includes('từ') || text.includes('đến') || text.includes('tới');
  const rangeMatch = /(\d+)\s*(?:-|–|—|đến|tới|to)\s*(?:phần\s*|part\s*)?(\d+)/.exec(text);
  if (
    rangeMatch &&
    (hasPartKeyword ||
      hasRangeWord ||
      /^\s*\d+\s*(?:-|–|—)\s*\d+\s*$/.test(text))
  ) {
    return [rangeMatch[1], rangeMatch[2]];
  }
  if (hasPartKeyword) {
    return (text.match(/\d+/g) ?? []).filter((n) => !isYearToken(n));
  }
  return [];
}

function extractYearFromVersion(versionText: string | null): number | null {
  // Fallback year from a parenthetical note, e.g.
  // "TCVN 13566 (từ 1 đến 10, 2019)" -> 2019.
  if (!versionText) return null;
  for (const token of versionText.match(/\d{4}/g) ?? []) {
    if (isYearToken(token)) return Number(token);
  }
  return null;
}

function expandRangeParts(parts: string[]): string[] | null {
  // Expand a two-endpoint range [start, end] into every part in between.
  if (parts.length !== 2) return null;
  if (!/^\d+$/.test(parts[0]) || !/^\d+$/.test(parts[1])) return null;
  const start = Number(parts[0]);
  const end = Number(parts[1]);
  if (start < 1 || end < start || end > MAX_PART_NUMBER) return null;
  if (end - start + 1 > MAX_EXPANDED_PARTS) return null;
  const out: string[] = [];
  for (let n = start; n <= end; n++) out.push(String(n));
  return out;
}

function partRangeKind(versionText: string | null): 'range' | 'list' | null {
  // Classify a parenthetical note as a part "range", a part "list", or null.
  if (!versionText) return null;
  const text = versionText.trim().toLowerCase();
  const hasPartKeyword = text.includes('phần') || text.includes('part');
  const hasRangeWord = text.includes('từ') || text.includes('đến') || text.includes('tới');
  const rangeMatch = /(\d+)\s*(?:-|–|—|đến|tới|to)\s*(?:phần\s*|part\s*)?(\d+)/.exec(text);
  if (
    rangeMatch &&
    (hasPartKeyword ||
      hasRangeWord ||
      /^\s*\d+\s*(?:-|–|—)\s*\d+\s*$/.test(text))
  ) {
    return 'range';
  }
  if (hasPartKeyword) return 'list';
  return null;
}

function expandedPartsFor(
  parts: string[],
  kind: 'range' | 'list' | null
): string[] | null {
  // Per-part expansion for a range/list, or null. Null for hierarchical
  // parts (kind null, e.g. "4-41" or "1-1"), a single part, and any
  // range/list that fails the safety guards.
  if (kind === 'range') return expandRangeParts(parts);
  if (kind === 'list') {
    if (parts.length < 2 || parts.length > MAX_EXPANDED_PARTS) return null;
    const numbers: number[] = [];
    for (const part of parts) {
      if (!/^\d+$/.test(part)) return null;
      numbers.push(Number(part));
    }
    if (numbers.some((n) => n < 1 || n > MAX_PART_NUMBER)) return null;
    return numbers.map((n) => String(n));
  }
  return null;
}

function extractVietnameseRangeFromRest(rest: string): [string[], string] {
  // Extract a 'từ X đến Y' / '-X đến Y' range outside parentheses.
  // Returns (parts, cleaned_rest); the range segment is removed so a
  // following ":2019" / " 2019" can still be parsed as the year.
  const m = /(?:từ\s*)?-?\s*(\d+)\s*(?:đến|tới)\s*(?:phần\s*)?(\d+)/iu.exec(rest ?? '');
  if (!m) return [[], rest];
  const parts = [m[1], m[2]];
  const cleaned = (rest.slice(0, m.index) + rest.slice(m.index + m[0].length)).trim();
  return [parts, cleaned];
}

function versionTextIsStandardCode(versionText: string | null): boolean {
  // True when a parenthetical note is itself a standard code (an
  // *equivalent* designation), e.g. "(BS EN 13146-1 đến 10:2019)".
  if (!versionText) return false;
  const upper = versionText.trim().toUpperCase();
  if (!/\d/.test(upper)) return false;
  return EQUIVALENT_ORGS.some(
    (org) => upper === org || upper.startsWith(org + ' ') || upper.startsWith(org + '/')
  );
}

export function parseStandardCode(rawCode: string): ParsedStandardCode {
  const raw = rawCode ?? '';
  let text = normalizeText(raw);

  const result: ParsedStandardCode = {
    raw_code: raw,
    normalized_code: text,

    org_prefix: null,
    org_normalized: null,
    org_confidence: 0.0,

    series_number: null,
    series_letter: null,

    std_main_number: null,
    std_part: null,
    std_parts: [],
    std_code_full: null,
    // Part-expansion provenance. "range" = every part between two
    // endpoints, "list" = exactly the listed parts, null = any other
    // case, which is not expanded. In particular a bare hyphen code
    // "MAIN-A-B" is NOT a range: it is Part A, Chapter B.
    parts_kind: null,
    expanded_parts: null,

    std_year: null,
    amendment: null,
    suffix: null,
    version_text: null,
    equivalent_text: null,

    confidence_score: 0.0,
    confidence_breakdown: {},
    // Deterministic verification flag. False on a parse failure and
    // until the confidence threshold below is met.
    verified: false
  };

  // STEP 1 — VERSION (...)
  const versionMatch = /\((.*?)\)/.exec(text);
  if (versionMatch) {
    result.version_text = versionMatch[1].trim();
    text = text.replace(/\(.*?\)/g, '').trim();
  } else if (text.includes('(')) {
    // Unclosed parenthetical, e.g. "... (BS EN 13146-1 đến 10:2019".
    const idx = text.indexOf('(');
    const before = text.slice(0, idx);
    const note = text.slice(idx + 1);
    result.version_text = note.trim().replace(/\)+$/, '');
    text = before.trim();
  }
  if (versionTextIsStandardCode(result.version_text)) {
    result.equivalent_text = result.version_text;
  }

  // STEP 2 — ORG + MAIN (year is optional from here on)
  // Uppercase for matching only: this also fixes "Ulc 779-9" -> ULC.
  const upper = text.toUpperCase();
  const digitMatch = /\d/.exec(upper);
  if (!digitMatch) return result;

  const orgPart = upper.slice(0, digitMatch.index).trim();
  if (!orgPart) return result;
  const [orgPrefix, seriesLetter] = extractSeriesLetter(orgPart);
  result.org_prefix = orgPart;
  result.series_letter = seriesLetter;
  const [orgNorm, orgConf] = normalizeOrg(orgPrefix);
  result.org_normalized = orgNorm;
  result.org_confidence = orgConf;

  const remainder = upper.slice(digitMatch.index).trim();
  const mainMatch = /^(\d+(?:\.\d+)*)/.exec(remainder);
  if (!mainMatch) return result;
  const main = mainMatch[1];
  result.std_main_number = main;
  result.series_number = main;
  const rest = remainder.slice(main.length).trim();

  // STEP 3 — PARTS / YEAR / SUFFIX
  // Vietnamese range outside parentheses first, e.g.
  // "TCVN 13566 từ 1 đến 10:2019" -> range ["1", "10"], rest ":2019".
  const [rangeFromRest, restCleaned] = extractVietnameseRangeFromRest(rest);
  const remainderParsed = parseRemainder(restCleaned, orgNorm, orgPart);
  let parts = remainderParsed.parts;
  let year = remainderParsed.year;
  const suffix = remainderParsed.suffix;
  let partsKind: 'range' | 'list' | null = null;
  let expandedParts: string[] | null = null;
  if (remainderParsed.hasCommaList && parts.length >= 2) {
    // Comma list written after the first part, e.g.
    // "TCVN 13566-1,2,3,4,5:2022" -> parts 1..5, year 2022.
    partsKind = 'list';
    expandedParts = expandedPartsFor(parts, 'list');
  }
  if (rangeFromRest.length > 0 && parts.length === 0) {
    parts = rangeFromRest;
    partsKind = 'range';
    expandedParts = expandRangeParts(rangeFromRest);
  }
  if (result.equivalent_text === null) {
    // Only a plain part/year note may supply the outer code's
    // parts/year. An equivalent code in parentheses must NOT.
    if (parts.length === 0) {
      const versionParts = extractPartRangeFromVersion(result.version_text);
      if (versionParts.length > 0) {
        parts = versionParts;
        partsKind = partRangeKind(result.version_text);
        expandedParts = expandedPartsFor(versionParts, partsKind);
      }
    }
    if (year === null) {
      // Year carried only in the parenthetical note. An outside
      // year, when present, always wins.
      year = extractYearFromVersion(result.version_text);
    }
  }
  // Only an expansion of at least two parts is an expansion at all.
  if (!expandedParts || expandedParts.length < 2) {
    expandedParts = null;
    if (partsKind !== 'range' && partsKind !== 'list') partsKind = null;
  }
  // No bare hyphen expansion: "MAIN-A-B" with no range/list words is
  // Part A, Chapter B, a single document (e.g. "EN 1993-1-10").
  result.parts_kind = partsKind;
  result.expanded_parts = expandedParts;
  result.std_parts = parts;
  result.std_part = parts.length > 0 ? '-' + parts.join('-') : null;
  result.std_year = year;

  if (suffix) {
    let sfx = suffix.trim();
    if (sfx.startsWith('/')) sfx = sfx.slice(1).trim();
    if (sfx) {
      // TS-only fix (divergence from Python, user decision 2026-11-23):
      // recognize an amendment/corrigendum token with OR without a space
      // ("AMD 1:2016", "Cor 1:2019", "AC:2009") and normalize it to the
      // compact form ("AMD1:2016"). Python's "multi-word suffix is prose"
      // rule dropped the spaced form entirely, losing the amendment.
      const spacedAmend = /^(AMD|COR|AC|A)\s*(\d+)?\s*(?::\s*(\d{4}))?$/.exec(sfx);
      if (spacedAmend && (spacedAmend[2] !== undefined || spacedAmend[3] !== undefined)) {
        const normalizedAmend =
          spacedAmend[1] +
          (spacedAmend[2] ?? '') +
          (spacedAmend[3] ? `:${spacedAmend[3]}` : '');
        result.amendment = normalizedAmend;
        result.suffix = normalizedAmend;
      } else if (/\s/.test(sfx)) {
        // Multi-word remainder that is not an amendment. Python drops it
        // as surrounding prose; TS keeps it (space-stripped) in suffix so
        // the normalized_code built from it can never collide with the
        // base code's key (user decision 2026-11-23).
        result.suffix = sfx.replace(/\s+/g, '');
      } else {
        // A valid suffix is a single token (AC:2009, TCĐBVN, -02, +A1).
        const amendMatch = /(AC|A\d+|AMD\d+|COR\d+):?(\d{4})?/.exec(sfx);
        if (amendMatch) result.amendment = amendMatch[0];
        result.suffix = sfx;
      }
    }
  }

  // STEP 4 — BUILD FULL CODE (main + parts, as before)
  result.std_code_full =
    result.std_parts.length > 0 ? `${main}-${result.std_parts.join('-')}` : main;

  // STEP 5 — CONFIDENCE
  const [score, breakdown] = computeConfidence(result);
  result.confidence_score = score;
  result.confidence_breakdown = breakdown;
  result.verified =
    result.std_main_number !== null &&
    result.std_year !== null &&
    Math.round(score * 1000) >= 800;

  return result;
}

// Port of parse_data pipeline.build_canonical_code: rebuild
// ``ORG MAIN[-PARTS]:YEAR[/SUFFIX]`` from a parsed result. ``org``
// overrides the organization (default: the normalized org).
export function buildCanonicalCode(
  parsed: ParsedStandardCode,
  org?: string | null
): string | null {
  const main = parsed.std_main_number;
  if (!main) return null;
  const orgUsed = org || parsed.org_normalized || parsed.org_prefix;
  const parts = parsed.std_parts ?? [];
  let code = parts.length > 0 ? `${main}-${parts.join('-')}` : String(main);
  if (parsed.series_letter) code = `${parsed.series_letter} ${code}`;
  if (orgUsed) code = `${orgUsed} ${code}`;
  if (parsed.std_year !== null) code = `${code}:${parsed.std_year}`;
  const suffix = parsed.suffix;
  if (suffix) {
    // Suffixes that already carry their own separator (+A1, -02, or a
    // leading ":") must not get an extra "/".
    if (suffix.startsWith('-') || suffix.startsWith('+') || suffix.startsWith(':')) {
      code = `${code}${suffix}`;
    } else {
      code = `${code}/${suffix}`;
    }
  }
  return code;
}

// -------------------------------------------------
// NORMALIZED CODE / BASE KEY (plan 4.1, user decision 2026-11-23)
// -------------------------------------------------
// normalized_code is built from org_prefix (the designation as written,
// e.g. "BS EN ISO", "TCVN ISO", "GB/T") normalized — uppercase, spaces
// stripped, '/', '-' and ':' KEPT — plus number + part + year (+ suffix).
// Each designation is a separate record: "ISO 9001:2015", "EN ISO
// 9001:2015", "BS EN ISO 9001:2015" and "TCVN ISO 9001:2015" all have
// DIFFERENT keys (adoptions are linked with `equivalent` relations, not
// merged). The same designation written differently ("TCVN9386-1:2012",
// "tcvn 9386-1:2012", "TCVN 9386-1:2012") yields the SAME key. The `org`
// column stored in the DB is org_normalized, NOT this prefix.
// base_key is the same construction without year and without suffix, for
// lookups where the user did not type a year.

function normalizedOrgPrefixComponent(orgPrefix: string | null): string | null {
  if (!orgPrefix) return null;
  // Collapse an exact duplicate prefix ("ENEN" / "EN EN" -> "EN") and drop
  // the "Std" token ("IEEE Std" -> "IEEE") exactly like normalizeOrg, so
  // spelling variants of one designation converge on one key. The series
  // letter stays part of the prefix ("JIS E" -> "JISE", "ASTMD" -> "ASTMD").
  let cleaned = removeRepeatedOrgPrefix(orgPrefix);
  cleaned = cleaned.replace(/(?:^|[\s-])STD(?:$|[\s-])/g, ' ');
  cleaned = cleaned.replace(/\s+/g, '').toUpperCase();
  return cleaned.length > 0 ? cleaned : null;
}

function buildKey(
  parsed: ParsedStandardCode,
  partOverride: string | null | undefined,
  includeYearAndSuffix: boolean
): string | null {
  const main = parsed.std_main_number;
  if (!main) return null;
  const org = normalizedOrgPrefixComponent(parsed.org_prefix);
  if (!org) return null;
  const part =
    partOverride !== undefined
      ? partOverride
      : parsed.std_parts.length > 0
        ? parsed.std_parts.join('-')
        : null;
  let key = org + main;
  if (part) key += `-${part}`;
  if (includeYearAndSuffix) {
    if (parsed.std_year !== null) key += `:${parsed.std_year}`;
    if (parsed.suffix) {
      const sfx = parsed.suffix.replace(/\s+/g, '').toUpperCase();
      // Suffixes that already carry their own separator (+A1, -02, or a
      // leading ":") must not get an extra "/".
      key +=
        sfx.startsWith('-') || sfx.startsWith('+') || sfx.startsWith(':')
          ? sfx
          : `/${sfx}`;
    }
  }
  return key;
}

/**
 * normalized_code for a parsed code. `partOverride` replaces the parsed
 * part string (used when one record is stored per expanded part).
 * Returns null when the code does not parse — never invent a key.
 */
export function buildNormalizedCode(
  parsed: ParsedStandardCode,
  partOverride?: string | null
): string | null {
  return buildKey(parsed, partOverride, true);
}

/** base_key: normalized_code without year and without suffix. */
export function buildBaseKey(
  parsed: ParsedStandardCode,
  partOverride?: string | null
): string | null {
  return buildKey(parsed, partOverride, false);
}

// -------------------------------------------------
// PER-PART EXPANSION FOR INGEST (user decision 2026-11-23)
// -------------------------------------------------
// When expanded_parts is non-null, ingest stores one record per part
// (year kept on each). When it is null — including an over-guard range
// such as "TCVN 1234-1 đến 200:2020" where parts_kind is "range" but the
// expansion guards refused — ingest stores a SINGLE record keeping the
// raw part string, with parse_confidence capped low (the identity of the
// record is uncertain) and never auto-splits.
const UNEXPANDABLE_CONFIDENCE_CAP = 0.5;

export interface ExpandedCodeRecord {
  part: string | null;
  normalized_code: string;
  base_key: string;
  parse_confidence: number;
}

export function expandParsedCode(parsed: ParsedStandardCode): ExpandedCodeRecord[] {
  if (!parsed.std_main_number) return [];
  if (parsed.expanded_parts !== null && parsed.expanded_parts.length > 0) {
    const records: ExpandedCodeRecord[] = [];
    for (const part of parsed.expanded_parts) {
      const normalized = buildNormalizedCode(parsed, part);
      const base = buildBaseKey(parsed, part);
      if (normalized === null || base === null) return [];
      records.push({
        part,
        normalized_code: normalized,
        base_key: base,
        parse_confidence: parsed.confidence_score
      });
    }
    return records;
  }
  const normalized = buildNormalizedCode(parsed);
  const base = buildBaseKey(parsed);
  if (normalized === null || base === null) return [];
  const confidence =
    parsed.parts_kind !== null
      ? Math.min(parsed.confidence_score, UNEXPANDABLE_CONFIDENCE_CAP)
      : parsed.confidence_score;
  return [
    {
      part: parsed.std_parts.length > 0 ? parsed.std_parts.join('-') : null,
      normalized_code: normalized,
      base_key: base,
      parse_confidence: confidence
    }
  ];
}

// Back-compat alias (Phase 1 name). Prefer buildNormalizedCode.
export function normalizedMergeKey(parsed: ParsedStandardCode): string | null {
  return buildNormalizedCode(parsed);
}
